-- Run after platform-user-deletion.sql in the same rollback-only transaction.
reset role;
select set_config('aura.owner_uid',gen_random_uuid()::text,true),set_config('aura.owner_clinic',gen_random_uuid()::text,true);
insert into auth.users(id,email,email_confirmed_at,is_anonymous) values(current_setting('aura.owner_uid')::uuid,'delete-owner@example.invalid',now(),false);
insert into aura_private.licenses(email,status) values('delete-owner@example.invalid','active');
insert into public.aura_clinics(id,owner_id,name,data) values(current_setting('aura.owner_clinic')::uuid,current_setting('aura.owner_uid')::uuid,'Disposable owner clinic','{}');
insert into public.aura_members(clinic_id,email,role) values(current_setting('aura.owner_clinic')::uuid,'delete-owner@example.invalid','manager'),(current_setting('aura.owner_clinic')::uuid,'security-two@example.invalid','manager');
insert into public.aura_history(clinic_id,actor,action,data,revision) values(current_setting('aura.owner_clinic')::uuid,'delete-owner@example.invalid','Fixture','{}',0);
select set_config('aura.owner_body',jsonb_build_object('email','delete-owner@example.invalid','user_id',current_setting('aura.owner_uid'),'confirmation','delete-owner@example.invalid')::text,true);
set local role authenticated;
select pg_temp.as_user('admin','aal2');
select set_config('aura.owner_preview',(select l->'owned_clinics' from jsonb_array_elements(public.aura_admin_rpc('list','{}')->'licenses') l where l->>'email'='delete-owner@example.invalid')::text,true);
select pg_temp.check_ok((current_setting('aura.owner_preview')::jsonb->0->>'members')::int=2,'owner preview shows clinic access impact');
select pg_temp.admin_denied(current_setting('aura.owner_body')::jsonb);
select pg_temp.admin_denied(current_setting('aura.owner_body')::jsonb||jsonb_build_object('delete_owned_clinics',true,'owned_clinics','[]'::jsonb));
select pg_temp.admin_denied(current_setting('aura.owner_body')::jsonb||jsonb_build_object('delete_owned_clinics',true,'owned_clinics',jsonb_set(current_setting('aura.owner_preview')::jsonb,'{0,id}',to_jsonb(current_setting('aura.clinic2')))));
reset role;
update public.aura_clinics set revision=revision+1 where id=current_setting('aura.owner_clinic')::uuid;
set local role authenticated;
select pg_temp.admin_denied(current_setting('aura.owner_body')::jsonb||jsonb_build_object('delete_owned_clinics',true,'owned_clinics',current_setting('aura.owner_preview')::jsonb));
select set_config('aura.owner_preview',(select l->'owned_clinics' from jsonb_array_elements(public.aura_admin_rpc('list','{}')->'licenses') l where l->>'email'='delete-owner@example.invalid')::text,true);
select pg_temp.check_ok((public.aura_admin_rpc('delete_user',current_setting('aura.owner_body')::jsonb||jsonb_build_object('delete_owned_clinics',true,'owned_clinics',current_setting('aura.owner_preview')::jsonb))->>'deleted_clinics')::int=1,'explicit owner deletion succeeds');
reset role;
select pg_temp.check_ok(not exists(select 1 from auth.users where id=current_setting('aura.owner_uid')::uuid),'owner login removed');
select pg_temp.check_ok(not exists(select 1 from public.aura_clinics where id=current_setting('aura.owner_clinic')::uuid),'only confirmed owned clinic removed');
select pg_temp.check_ok(not exists(select 1 from public.aura_members where clinic_id=current_setting('aura.owner_clinic')::uuid),'deleted clinic memberships cascade removed');
select pg_temp.check_ok(not exists(select 1 from public.aura_history where clinic_id=current_setting('aura.owner_clinic')::uuid),'deleted clinic history cascade removed');
select pg_temp.check_ok(exists(select 1 from aura_private.platform_audit where action='admin.delete_user' and target='delete-owner@example.invalid' and details->'clinical_history_preserved'='false'::jsonb),'audit records owned clinic deletion');
select pg_temp.check_ok((select jsonb_agg(to_jsonb(c) order by id)::text from public.aura_clinics c where id in (current_setting('aura.clinic1')::uuid,current_setting('aura.clinic2')::uuid))=current_setting('aura.preserved_clinics'),'other clinics untouched by owner deletion');
